//! Parses one input line into a typed [`Command`].
//!
//! This performs the checks that need no broker state: request shape, required
//! parameters and parameter values (steps 1 to 3 of the error order in the spec).

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Code, Error, Result};

const VISIBILITY_TIMEOUT: RangeInclusive<u32> = 0..=43_200;
const DELAY_SECONDS: RangeInclusive<u32> = 0..=900;
const RETENTION_SECONDS: RangeInclusive<u32> = 60..=1_209_600;
const MAX_RECEIVE_COUNT: RangeInclusive<u32> = 1..=1000;
const TICK_SECONDS: RangeInclusive<u32> = 0..=1_209_600;

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

/// Queue attributes as given in a request; `None` means absent.
#[derive(Debug, Default)]
pub struct Attributes {
    pub visibility_timeout: Option<u32>,
    pub delay_seconds: Option<u32>,
    pub retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u32>,
}

#[derive(Debug)]
pub enum Command {
    CreateQueue { name: String, attributes: Attributes },
    SetQueueAttributes { name: String, attributes: Attributes },
    GetQueueAttributes { name: String },
    ListQueues { prefix: Option<String> },
    DeleteQueue { name: String },
    PurgeQueue { name: String },
    Tick { seconds: u32 },
}

pub fn parse(line: &[u8]) -> Result<Command> {
    let request = |why: &str| Error::new(Code::InvalidRequest, why);
    let text = std::str::from_utf8(line).map_err(|_| request("line is not valid UTF-8"))?;
    let value: Value =
        serde_json::from_str(text).map_err(|e| request(&format!("line is not JSON: {e}")))?;
    let Value::Object(object) = value else {
        return Err(request("line is not a JSON object"));
    };
    let Some(Value::String(command)) = object.get("Command") else {
        return Err(request("Command must be a string"));
    };
    let p = Params(&object);

    match command.as_str() {
        "CreateQueue" => {
            p.require(&["QueueName"])?;
            let name = p.required_string("QueueName")?;
            if !is_valid_queue_name(name) {
                return Err(Error::new(Code::QueueNameInvalid, format!("invalid queue name {name:?}")));
            }
            Ok(Command::CreateQueue { name: name.to_owned(), attributes: p.attributes()? })
        }
        "SetQueueAttributes" => {
            p.require(&["QueueName", "Attributes"])?;
            let name = p.queue_name()?;
            Ok(Command::SetQueueAttributes { name, attributes: p.attributes()? })
        }
        "GetQueueAttributes" => Ok(Command::GetQueueAttributes { name: p.queue_name_required()? }),
        "ListQueues" => Ok(Command::ListQueues { prefix: p.string("Prefix")?.map(str::to_owned) }),
        "DeleteQueue" => Ok(Command::DeleteQueue { name: p.queue_name_required()? }),
        "PurgeQueue" => Ok(Command::PurgeQueue { name: p.queue_name_required()? }),
        "Tick" => {
            p.require(&["Seconds"])?;
            Ok(Command::Tick { seconds: p.required_integer("Seconds", TICK_SECONDS)? })
        }
        other => Err(request(&format!("unknown command {other:?}"))),
    }
}

/// 1 to 80 characters of `A-Z a-z 0-9 _ -`, or 1 to 75 of them followed by `.fifo`.
fn is_valid_queue_name(name: &str) -> bool {
    let stem = name.strip_suffix(".fifo").unwrap_or(name);
    let len_ok = (1..=75).contains(&stem.len()) || (stem.len() == name.len() && stem.len() <= 80);
    len_ok && stem.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// The members of a request or of its `Attributes`, where `null` counts as absent.
struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| self.get(name).is_none()) {
            Some(name) => Err(missing(name)),
            None => Ok(()),
        }
    }

    fn string(&self, name: &str) -> Result<Option<&'a str>> {
        let wrong = || invalid(name, "must be a string");
        self.get(name).map(|v| v.as_str().ok_or_else(wrong)).transpose()
    }

    fn required_string(&self, name: &str) -> Result<&'a str> {
        self.string(name)?.ok_or_else(|| missing(name))
    }

    fn boolean(&self, name: &str) -> Result<Option<bool>> {
        let wrong = || invalid(name, "must be a boolean");
        self.get(name).map(|v| v.as_bool().ok_or_else(wrong)).transpose()
    }

    fn integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        let wrong = || {
            invalid(name, &format!("must be an integer from {} to {}", range.start(), range.end()))
        };
        let parse = |v: &Value| {
            let n = v.as_u64().and_then(|n| u32::try_from(n).ok())?;
            range.contains(&n).then_some(n)
        };
        self.get(name).map(|v| parse(v).ok_or_else(wrong)).transpose()
    }

    fn required_integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<u32> {
        self.integer(name, range)?.ok_or_else(|| missing(name))
    }

    fn queue_name(&self) -> Result<String> {
        self.required_string("QueueName").map(str::to_owned)
    }

    /// For commands whose only required parameter is `QueueName`.
    fn queue_name_required(&self) -> Result<String> {
        self.require(&["QueueName"])?;
        self.queue_name()
    }

    /// The optional `Attributes` object; absent means no attributes.
    fn attributes(&self) -> Result<Attributes> {
        let wrong = || invalid("Attributes", "must be an object");
        let Some(value) = self.get("Attributes") else {
            return Ok(Attributes::default());
        };
        let map = value.as_object().ok_or_else(wrong)?;
        if let Some(unknown) = map.keys().find(|k| !ATTRIBUTE_NAMES.contains(&k.as_str())) {
            return Err(invalid("Attributes", &format!("unknown attribute {unknown:?}")));
        }
        let a = Params(map);
        Ok(Attributes {
            visibility_timeout: a.integer("VisibilityTimeout", VISIBILITY_TIMEOUT)?,
            delay_seconds: a.integer("DelaySeconds", DELAY_SECONDS)?,
            retention_seconds: a.integer("RetentionSeconds", RETENTION_SECONDS)?,
            fifo: a.boolean("Fifo")?,
            content_based_deduplication: a.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: a.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: a.integer("MaxReceiveCount", MAX_RECEIVE_COUNT)?,
        })
    }
}

fn missing(name: &str) -> Error {
    Error::new(Code::MissingParameter, format!("{name} is required"))
}

fn invalid(name: &str, why: &str) -> Error {
    Error::new(Code::InvalidParameterValue, format!("{name} {why}"))
}

#[cfg(test)]
mod tests {
    use super::is_valid_queue_name;

    #[test]
    fn queue_name_syntax() {
        let valid = ["a", "Jobs_1-x", "q.fifo", &"a".repeat(80), &format!("{}.fifo", "a".repeat(75))];
        for name in valid {
            assert!(is_valid_queue_name(name), "{name} should be valid");
        }
        let invalid = ["", ".fifo", "a.b", "a b", "é", "a.fifo.fifo", &"a".repeat(81), &format!("{}.fifo", "a".repeat(76))];
        for name in invalid {
            assert!(!is_valid_queue_name(name), "{name} should be invalid");
        }
    }
}
