//! One queue: its configuration, messages in arrival order and bookkeeping.

use std::collections::{BTreeMap, HashMap};

pub const MAX_MESSAGES: usize = 100_000;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Config {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

#[derive(Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub group_id: Option<String>,
    pub sequence_number: Option<u64>,
    pub receive_count: u32,
    pub first_received_at: Option<u64>,
    /// Delayed while `now < delayed_until`.
    pub delayed_until: u64,
    /// In flight while `now < in_flight_until`.
    pub in_flight_until: u64,
    /// The latest receipt handle issued for this message.
    pub handle: Option<u64>,
}

impl Message {
    pub fn is_delayed(&self, now: u64) -> bool {
        now < self.delayed_until
    }

    pub fn is_in_flight(&self, now: u64) -> bool {
        !self.is_delayed(now) && now < self.in_flight_until
    }

    pub fn is_visible(&self, now: u64) -> bool {
        !self.is_delayed(now) && !self.is_in_flight(now)
    }
}

/// What a FIFO queue remembers about an accepted deduplication id.
#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub at: u64,
    pub message_id: u64,
    pub sequence_number: u64,
}

#[derive(Debug)]
pub struct Queue {
    pub config: Config,
    /// Keyed by an arrival counter, so iteration is arrival order.
    messages: BTreeMap<u64, Message>,
    next_key: u64,
    next_sequence: u64,
    /// Handle number to the arrival key of the message it was issued for.
    handles: HashMap<u64, u64>,
    pub dedup: HashMap<String, Accepted>,
    /// Lower bound of the `sent_at` of all messages; lets `expire` skip the scan.
    oldest_sent_at: u64,
}

impl Queue {
    pub fn new(config: Config) -> Self {
        Self {
            config,
            messages: BTreeMap::new(),
            next_key: 0,
            next_sequence: 1,
            handles: HashMap::new(),
            dedup: HashMap::new(),
            oldest_sent_at: u64::MAX,
        }
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    pub fn messages(&self) -> impl Iterator<Item = (u64, &Message)> {
        self.messages.iter().map(|(&key, m)| (key, m))
    }

    pub fn get_mut(&mut self, key: u64) -> Option<&mut Message> {
        self.messages.get_mut(&key)
    }

    /// Appends a message and returns its sequence number if this is a FIFO queue.
    pub fn push(&mut self, mut message: Message) -> Option<u64> {
        message.sequence_number = self.config.fifo.then(|| {
            let n = self.next_sequence;
            self.next_sequence += 1;
            n
        });
        let sequence = message.sequence_number;
        self.oldest_sent_at = self.oldest_sent_at.min(message.sent_at);
        self.messages.insert(self.next_key, message);
        self.next_key += 1;
        sequence
    }

    pub fn remove(&mut self, key: u64) -> Option<Message> {
        let message = self.messages.remove(&key)?;
        if let Some(handle) = message.handle {
            self.handles.remove(&handle);
        }
        Some(message)
    }

    pub fn clear(&mut self) {
        self.messages.clear();
        self.handles.clear();
        self.oldest_sent_at = u64::MAX;
    }

    pub fn register_handle(&mut self, key: u64, handle: u64) {
        if let Some(old) = self.messages.get_mut(&key).and_then(|m| m.handle.replace(handle)) {
            self.handles.remove(&old);
        }
        self.handles.insert(handle, key);
    }

    /// The message that `handle` was issued for, if it is its latest handle and the
    /// message is in flight.
    pub fn find_in_flight(&mut self, handle: u64, now: u64) -> Option<(u64, &mut Message)> {
        let key = *self.handles.get(&handle)?;
        let message = self.messages.get_mut(&key)?;
        (message.handle == Some(handle) && message.is_in_flight(now)).then_some((key, message))
    }

    /// Removes the messages whose retention has run out.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.config.retention_seconds);
        if now < self.oldest_sent_at.saturating_add(retention) {
            return;
        }
        let mut oldest = u64::MAX;
        let handles = &mut self.handles;
        self.messages.retain(|_, m| {
            let expired = now >= m.sent_at + retention;
            if expired {
                if let Some(handle) = m.handle {
                    handles.remove(&handle);
                }
            } else {
                oldest = oldest.min(m.sent_at);
            }
            !expired
        });
        self.oldest_sent_at = oldest;
    }

    /// Counts of visible, in-flight and delayed messages.
    pub fn counts(&self, now: u64) -> (usize, usize, usize) {
        self.messages.values().fold((0, 0, 0), |(v, f, d), m| {
            if m.is_delayed(now) {
                (v, f, d + 1)
            } else if m.is_in_flight(now) {
                (v, f + 1, d)
            } else {
                (v + 1, f, d)
            }
        })
    }
}
