//! Executes commands against the in-memory state (steps 4 and 5 of the error order).

use std::collections::{BTreeMap, HashSet};
use std::ops::Bound;

use serde_json::{Value, json};

use crate::command::{self, Attributes, Command};
use crate::error::{Code, Error, Result};
use crate::queue::{Accepted, Config, DeadLetter, MAX_MESSAGES, Message, Queue};

const MAX_QUEUES: usize = 1000;
const DEDUP_WINDOW: u64 = 300;

#[derive(Default)]
pub struct Broker {
    queues: BTreeMap<String, Queue>,
    now: u64,
    next_message: u64,
    next_handle: u64,
}

impl Broker {
    pub fn new() -> Self {
        Self { next_message: 1, next_handle: 1, ..Self::default() }
    }

    /// Runs one input line and returns its response object.
    pub fn handle_line(&mut self, line: &[u8]) -> Value {
        match command::parse(line).and_then(|c| self.execute(c)) {
            Ok(mut result) => {
                result["ok"] = true.into();
                result
            }
            Err(e) => json!({"ok": false, "error": {"code": e.code.as_str(), "message": e.message}}),
        }
    }

    fn execute(&mut self, command: Command) -> Result<Value> {
        let now = self.now;
        match command {
            Command::CreateQueue { name, attributes } => self.create_queue(name, attributes),
            Command::SetQueueAttributes { name, attributes } => self.set_attributes(&name, attributes),
            Command::GetQueueAttributes { name } => {
                let q = live(&mut self.queues, &name, now)?;
                let c = &q.config;
                let mut attributes = json!({
                    "VisibilityTimeout": c.visibility_timeout, "DelaySeconds": c.delay_seconds,
                    "RetentionSeconds": c.retention_seconds, "Fifo": c.fifo,
                    "ContentBasedDeduplication": c.content_based_deduplication,
                });
                if let Some(d) = &c.dead_letter {
                    attributes["DeadLetterQueue"] = json!(d.queue);
                    attributes["MaxReceiveCount"] = json!(d.max_receive_count);
                }
                let (visible, in_flight, delayed) = q.counts(now);
                let counts = json!({"Visible": visible, "InFlight": in_flight, "Delayed": delayed});
                Ok(json!({"Attributes": attributes, "Counts": counts}))
            }
            Command::ListQueues { prefix } => {
                let prefix = prefix.as_deref().unwrap_or("");
                let names: Vec<&String> = self
                    .queues
                    .range::<str, _>((Bound::Included(prefix), Bound::Unbounded))
                    .map(|(name, _)| name)
                    .take_while(|name| name.starts_with(prefix))
                    .collect();
                Ok(json!({"QueueNames": names}))
            }
            Command::DeleteQueue { name } => {
                self.queues.remove(&name).ok_or_else(|| no_queue(&name))?;
                for q in self.queues.values_mut() {
                    if q.config.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                        q.config.dead_letter = None;
                    }
                }
                Ok(json!({}))
            }
            Command::PurgeQueue { name } => {
                live(&mut self.queues, &name, now)?.clear();
                Ok(json!({}))
            }
            Command::Tick { seconds } => {
                self.now += u64::from(seconds);
                Ok(json!({"Now": self.now}))
            }
            Command::SendMessage { queue, body, delay_seconds, group_id, deduplication_id } => {
                self.send(&queue, body, delay_seconds, group_id, deduplication_id)
            }
            Command::ReceiveMessage { queue, max_messages, visibility_timeout } => {
                self.receive(&queue, max_messages as usize, visibility_timeout)
            }
            Command::DeleteMessage { queue, receipt_handle } => {
                let (handle, q) = self.handle_and_queue(&queue, &receipt_handle)?;
                let (key, _) = q.find_in_flight(handle, now).ok_or_else(expired)?;
                q.remove(key);
                Ok(json!({}))
            }
            Command::ChangeMessageVisibility { queue, receipt_handle, visibility_timeout } => {
                let (handle, q) = self.handle_and_queue(&queue, &receipt_handle)?;
                let (_, message) = q.find_in_flight(handle, now).ok_or_else(expired)?;
                message.in_flight_until = now + u64::from(visibility_timeout);
                Ok(json!({}))
            }
        }
    }

    fn create_queue(&mut self, name: String, a: Attributes) -> Result<Value> {
        let fifo = a.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return Err(Error::new(Code::QueueNameInvalid, "a queue name ends in .fifo exactly when Fifo is true"));
        }
        let cbd = a.content_based_deduplication.unwrap_or(false);
        if cbd && !fifo {
            return Err(bad("ContentBasedDeduplication requires a FIFO queue"));
        }
        let dead_letter = dead_letter_of(a.dead_letter_queue, a.max_receive_count)?;
        let defaults = Config::default();
        let config = Config {
            visibility_timeout: a.visibility_timeout.unwrap_or(defaults.visibility_timeout),
            delay_seconds: a.delay_seconds.unwrap_or(defaults.delay_seconds),
            retention_seconds: a.retention_seconds.unwrap_or(defaults.retention_seconds),
            fifo,
            content_based_deduplication: cbd,
            dead_letter,
        };
        if let Some(existing) = self.queues.get(&name) {
            return if existing.config == config {
                Ok(json!({}))
            } else {
                Err(Error::new(Code::QueueAlreadyExists, format!("queue {name:?} exists with other attributes")))
            };
        }
        if let Some(d) = &config.dead_letter {
            let target = self.queues.get(&d.queue).ok_or_else(|| no_queue(&d.queue))?;
            if target.config.fifo != fifo {
                return Err(bad("the dead-letter queue must be of the same type"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(Code::LimitExceeded, "at most 1000 queues"));
        }
        self.queues.insert(name, Queue::new(config));
        Ok(json!({}))
    }

    fn set_attributes(&mut self, name: &str, a: Attributes) -> Result<Value> {
        let now = self.now;
        let q = live(&mut self.queues, name, now)?;
        if a.fifo.is_some() {
            return Err(Error::new(Code::UnsupportedOperation, "the type of a queue cannot change"));
        }
        if a.content_based_deduplication == Some(true) && !q.config.fifo {
            return Err(bad("ContentBasedDeduplication requires a FIFO queue"));
        }
        let dead_letter = dead_letter_of(a.dead_letter_queue, a.max_receive_count)?;
        let fifo = q.config.fifo;
        if let Some(d) = &dead_letter {
            let target = self.queues.get(&d.queue).ok_or_else(|| no_queue(&d.queue))?;
            if d.queue == name || target.config.fifo != fifo {
                return Err(bad("invalid dead-letter queue"));
            }
        }
        let c = &mut live(&mut self.queues, name, now)?.config;
        c.visibility_timeout = a.visibility_timeout.unwrap_or(c.visibility_timeout);
        c.delay_seconds = a.delay_seconds.unwrap_or(c.delay_seconds);
        c.retention_seconds = a.retention_seconds.unwrap_or(c.retention_seconds);
        c.content_based_deduplication = a.content_based_deduplication.unwrap_or(c.content_based_deduplication);
        c.dead_letter = dead_letter.or(c.dead_letter.take());
        Ok(json!({}))
    }

    fn send(
        &mut self,
        queue: &str,
        body: String,
        delay: Option<u32>,
        group_id: Option<String>,
        dedup_id: Option<String>,
    ) -> Result<Value> {
        let now = self.now;
        let q = live(&mut self.queues, queue, now)?;
        let fifo = q.config.fifo;
        if (!fifo && (group_id.is_some() || dedup_id.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(Code::UnsupportedOperation, "parameter not supported by this queue type"));
        }
        if fifo {
            if group_id.is_none() {
                return Err(Error::new(Code::MissingParameter, "GroupId is required"));
            }
            if dedup_id.is_none() && !q.config.content_based_deduplication {
                return Err(Error::new(Code::MissingParameter, "DeduplicationId is required"));
            }
            let id = dedup_id.as_deref().unwrap_or(&body);
            if let Some(seen) = q.dedup.get(id).filter(|s| now - s.at < DEDUP_WINDOW) {
                return Ok(json!({"MessageId": message_id(seen.message_id), "SequenceNumber": seen.sequence_number}));
            }
        }
        if q.len() >= MAX_MESSAGES {
            return Err(Error::new(Code::LimitExceeded, "a queue holds at most 100000 messages"));
        }
        let id = self.next_message;
        self.next_message += 1;
        let delay = delay.unwrap_or(q.config.delay_seconds);
        let dedup_key = fifo.then(|| dedup_id.unwrap_or_else(|| body.clone()));
        let sequence = q.push(Message {
            id,
            body,
            sent_at: now,
            group_id,
            sequence_number: None,
            receive_count: 0,
            first_received_at: None,
            delayed_until: now + u64::from(delay),
            in_flight_until: 0,
            handle: None,
        });
        let mut result = json!({"MessageId": message_id(id)});
        if let (Some(key), Some(sequence_number)) = (dedup_key, sequence) {
            q.dedup.insert(key, Accepted { at: now, message_id: id, sequence_number });
            result["SequenceNumber"] = json!(sequence_number);
        }
        Ok(result)
    }

    fn receive(&mut self, queue: &str, max: usize, visibility: Option<u32>) -> Result<Value> {
        let now = self.now;
        let q = live(&mut self.queues, queue, now)?;
        let visibility = u64::from(visibility.unwrap_or(q.config.visibility_timeout));
        let dead_letter = q.config.dead_letter.clone();
        let fifo = q.config.fifo;

        // Examine messages in arrival order, remembering what to do with each.
        let (mut deliver, mut moves) = (Vec::new(), Vec::new());
        let mut groups_in_queue: HashSet<&str> = HashSet::new();
        for (key, m) in q.messages() {
            if m.group_id.as_deref().is_some_and(|g| groups_in_queue.contains(g)) {
                continue;
            }
            if m.is_visible(now) {
                if dead_letter.as_ref().is_some_and(|d| m.receive_count >= d.max_receive_count) {
                    moves.push(key);
                    continue;
                }
                deliver.push(key);
            }
            if let Some(g) = m.group_id.as_deref() {
                groups_in_queue.insert(g);
            }
            if deliver.len() == max {
                break;
            }
        }
        debug_assert!(fifo || groups_in_queue.is_empty());

        let mut messages = Vec::with_capacity(deliver.len());
        for key in deliver {
            let handle = self.next_handle;
            self.next_handle += 1;
            q.register_handle(key, handle);
            let m = q.get_mut(key).expect("key was found while scanning this queue");
            m.receive_count += 1;
            m.first_received_at.get_or_insert(now);
            m.in_flight_until = now + visibility;
            let mut out = json!({
                "MessageId": message_id(m.id), "ReceiptHandle": format!("r-{handle}"),
                "Body": m.body, "ReceiveCount": m.receive_count, "SentAt": m.sent_at,
                "FirstReceivedAt": m.first_received_at,
            });
            if let (Some(g), Some(s)) = (&m.group_id, m.sequence_number) {
                out["GroupId"] = json!(g);
                out["SequenceNumber"] = json!(s);
            }
            messages.push(out);
        }

        if let Some(d) = dead_letter {
            let moved: Vec<Message> = moves
                .into_iter()
                .map(|key| q.remove(key).expect("key was found while scanning this queue"))
                .collect();
            let target = self.queues.get_mut(&d.queue).expect("a configured dead-letter queue exists");
            for mut m in moved {
                m.receive_count = 0;
                m.first_received_at = None;
                m.delayed_until = 0;
                m.in_flight_until = 0;
                m.handle = None;
                target.push(m);
            }
        }
        Ok(json!({"Messages": messages}))
    }

    /// Looks up the queue, then validates the receipt handle's form (spec section 6, rule 1).
    fn handle_and_queue(&mut self, queue: &str, handle: &str) -> Result<(u64, &mut Queue)> {
        let now = self.now;
        let issued = self.next_handle;
        let q = live(&mut self.queues, queue, now)?;
        let number = handle
            .strip_prefix("r-")
            .filter(|n| !n.starts_with('0') && n.bytes().all(|b| b.is_ascii_digit()))
            .and_then(|n| n.parse::<u64>().ok())
            .filter(|&n| n < issued)
            .ok_or_else(|| Error::new(Code::ReceiptHandleInvalid, format!("handle {handle:?} was never issued")))?;
        Ok((number, q))
    }
}

/// Finds a queue and drops its messages whose retention has run out.
fn live<'a>(queues: &'a mut BTreeMap<String, Queue>, name: &str, now: u64) -> Result<&'a mut Queue> {
    let q = queues.get_mut(name).ok_or_else(|| no_queue(name))?;
    q.expire(now);
    Ok(q)
}

fn dead_letter_of(queue: Option<String>, max_receive_count: Option<u32>) -> Result<Option<DeadLetter>> {
    match (queue, max_receive_count) {
        (Some(queue), Some(max_receive_count)) => Ok(Some(DeadLetter { queue, max_receive_count })),
        (None, None) => Ok(None),
        _ => Err(bad("DeadLetterQueue and MaxReceiveCount must be given together")),
    }
}

fn message_id(n: u64) -> String {
    format!("m-{n}")
}

fn bad(message: &str) -> Error {
    Error::new(Code::InvalidParameterValue, message)
}

fn no_queue(name: &str) -> Error {
    Error::new(Code::QueueDoesNotExist, format!("queue {name:?} does not exist"))
}

